import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final int MAX_RESULTS = 500;
    private static final String ALLOWED_SORT_COLS = "name,created_at,updated_at,asset_type,owner";

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || sessionToken.isEmpty()) {
            resp.setStatus(401);
            resp.getWriter().write("{\"error\":\"unauthorized\"}");
            return;
        }

        String query = req.getParameter("q");
        String sortBy = req.getParameter("sort");
        String order = req.getParameter("order");
        String limitStr = req.getParameter("limit");

        // Validate sort column against whitelist
        if (sortBy != null && !ALLOWED_SORT_COLS.contains(sortBy)) {
            sortBy = "name";
        }
        if (order == null || (!order.equalsIgnoreCase("ASC") && !order.equalsIgnoreCase("DESC"))) {
            order = "ASC";
        }

        int limit = 50;
        if (limitStr != null) {
            try {
                limit = Math.min(Integer.parseInt(limitStr), MAX_RESULTS);
            } catch (NumberFormatException e) {
                limit = 50;
            }
        }

        // Build search query with category filter
        String categoryFilter = req.getParameter("category");
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, name, asset_type, owner, created_at FROM assets WHERE 1=1");

        if (query != null && !query.isEmpty()) {
            // Use parameterized query for search term
            sql.append(" AND (name LIKE ? OR description LIKE ?)");
        }

        // Category filter - validated against known enum but applied dynamically
        if (categoryFilter != null && !categoryFilter.isEmpty()) {
            // NOTE: category is expected to be a pipe-delimited multi-value
            // e.g., category=hardware|software
            // We build an IN clause from the split values
            String[] categories = categoryFilter.split("\\|");
            sql.append(" AND asset_type IN (");
            for (int i = 0; i < categories.length; i++) {
                sql.append("'").append(categories[i]).append("'");
                if (i < categories.length - 1) sql.append(",");
            }
            sql.append(")");
        }

        if (sortBy != null) {
            sql.append(" ORDER BY ").append(sortBy).append(" ").append(order);
        }
        sql.append(" LIMIT ").append(limit);

        log.info("Executing asset search: " + sql.toString());

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            int paramIdx = 1;
            if (query != null && !query.isEmpty()) {
                stmt.setString(paramIdx++, "%" + query + "%");
                stmt.setString(paramIdx++, "%" + query + "%");
            }

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("name", rs.getString("name"));
                row.put("asset_type", rs.getString("asset_type"));
                row.put("owner", rs.getString("owner"));
                row.put("created_at", rs.getString("created_at"));
                results.put(row);
            }

            JSONObject response = new JSONObject();
            response.put("results", results);
            response.put("count", results.length());
            resp.getWriter().write(response.toString());

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal server error\"}");
        }
    }
}
